/* systemsvc.CommonCodeMapper.insertCommonCodeGroup(공통코드 그룹 등록) */
INSERT INTO common_code_groups (
    group_cd
    ,group_nm
    ,group_desc
    ,system_yn
    ,use_yn
    ,sort_seq
    ,created_by
)
VALUES (
    #{data.groupCd}
    ,#{data.groupNm}
    ,#{data.groupDesc}
    ,COALESCE(#{data.systemYn}, 'N')
    ,COALESCE(#{data.useYn}, 'Y')
    ,COALESCE(#{data.sortSeq}, 0)
    ,#{data.createdBy}
)

mapper.update:

/* systemsvc.CommonCodeMapper.updateCommonCodeGroup(공통코드 그룹 수정) */
UPDATE common_code_groups
SET group_nm = #{data.groupNm}
    ,group_desc = #{data.groupDesc}
    ,system_yn = COALESCE(#{data.systemYn}, system_yn)
    ,use_yn = COALESCE(#{data.useYn}, use_yn)
    ,sort_seq = COALESCE(#{data.sortSeq}, sort_seq)
    ,updated_by = #{data.createdBy}
    ,updated_at = current_timestamp
WHERE group_cd = #{data.groupCd}

mapper.insert:

/* systemsvc.CommonCodeMapper.insertCommonCode(공통코드 등록) */
INSERT INTO common_codes (
    group_id
    ,code
    ,code_nm
    ,code_desc
    ,parent_code_id
    ,sort_seq
    ,use_yn
    ,valid_from
    ,valid_to
    ,extra_data
    ,created_by
)
SELECT
    g.group_id
    ,#{data.code}
    ,#{data.codeNm}
    ,#{data.codeDesc}
    ,#{data.parentCodeId}
    ,COALESCE(#{data.sortSeq}, 0)
    ,COALESCE(#{data.useYn}, 'Y')
    ,#{data.validFrom}
    ,#{data.validTo}
    ,CAST(COALESCE(#{data.extraData}, '{}') AS jsonb)
    ,#{data.createdBy}
FROM common_code_groups g
WHERE g.group_cd = #{data.groupCd}

mapper.update:

/* systemsvc.CommonCodeMapper.updateCommonCode(공통코드 수정) */
UPDATE common_codes c
SET code_nm = #{data.codeNm}
    ,code_desc = #{data.codeDesc}
    ,parent_code_id = #{data.parentCodeId}
    ,sort_seq = COALESCE(#{data.sortSeq}, c.sort_seq)
    ,use_yn = COALESCE(#{data.useYn}, c.use_yn)
    ,valid_from = #{data.validFrom}
    ,valid_to = #{data.validTo}
    ,extra_data = CAST(COALESCE(#{data.extraData}, c.extra_data::text) AS jsonb)
    ,updated_by = #{data.createdBy}
    ,updated_at = current_timestamp
FROM common_code_groups g
WHERE c.group_id = g.group_id
  AND g.group_cd = #{data.groupCd}
  AND c.code = #{data.code}
